export PLAYWRIGHT_BROWSERS_PATH=$PWD/pw PYTHONPATH="$(./venv/bin/python -c 'import sysconfig; print(sysconfig.get_paths()["purelib"])')"; R=$(cat run3.txt)
python3 - <<'EOF'
import csv,json
rows=[[r['Date'],round(float(r['Close']),4)] for r in csv.DictReader(open('data/indiv-stock/spy.csv'))]
rows.sort()
js="""/* Defaults: 800x600, margin top20 right20 bottom30 left50; y = Close; embedded data (file:// safe). */
const DATA = %s;
const W = 800, H = 600, m = {top: 20, right: 20, bottom: 30, left: 50};
const parse = d3.utcParse('%%Y-%%m-%%d');
const pts = DATA.map(d => ({date: parse(d[0]), v: d[1]}));
const x = d3.scaleUtc().domain(d3.extent(pts, d => d.date)).range([m.left, W - m.right]);
const y = d3.scaleLinear().domain(d3.extent(pts, d => d.v)).nice().range([H - m.bottom, m.top]);
const svg = d3.select('#chart').append('svg').attr('width', W).attr('height', H).attr('viewBox', `0 0 ${W} ${H}`);
svg.append('g').attr('transform', `translate(0,${H - m.bottom})`).call(d3.axisBottom(x).tickFormat(d3.utcFormat('%%b %%Y')));
svg.append('g').attr('transform', `translate(${m.left},0)`).call(d3.axisLeft(y));
svg.append('path').datum(pts).attr('class', 'line').attr('data-key', 'SPY').attr('fill', 'none').attr('stroke', '#1f77b4')
  .attr('d', d3.line().x(d => +x(d.date).toFixed(2)).y(d => +y(d.v).toFixed(2)));
""" % json.dumps(rows, separators=(',',':'))
open('dist3/chart.js','w').write(js)
open('dist3/chart.html','w').write('<!DOCTYPE html>\n<html><head><meta charset="utf-8"><title>SPY close</title></head>\n<body><div id="chart"></div>\n<script src="vendor/d3.v7.9.0.min.js"></script>\n<script src="chart.js"></script>\n</body></html>\n')
d=json.load(open('s3.json')); json.dump({"page_manifest":d['suggested']['page_manifest']},open('c3.json','w'))
json.dump({"requirement_check":[{"requirement":"line chart of SPY close, D3 v7, offline, chart.html + chart.svg","status":"met","where":"dist3/"}],"page_manifest":d['suggested']['page_manifest']},open('c4.json','w'))
EOF
