/*
 * Horizontal bar chart: market cap of the companies in stock-descriptions.csv.
 * Defaults chosen (task did not specify):
 *  - D3 v6.7.0, vendored locally at ../vendor/d3.v6.7.0.min.js (no CDN).
 *  - Size 800 x 600, viewBox "0 0 800 600"; margins top 40, right 20, bottom 40, left 60.
 *  - Rows with an empty marketCap (the 10 ETFs) are dropped -> 40 bars.
 *  - Sort: marketCap descending, ties by ticker ascending.
 *  - Y axis labels: ticker; full name shown in the tooltip.
 *  - Color: d3.scaleOrdinal(d3.schemeCategory10) over the sorted sector domain.
 *  - Legend inside the SVG (bottom-right of plot area, where bars are short) so the exported SVG keeps it.
 *  - Market cap format: \$ + 2 decimals + K/M/B/T suffix (e.g. \$2.68T); axis ticks use the same suffixes.
 *  - Data embedded below so the page works from file:// (offline).
 *  - No transitions, no randomness.
 */
(function () {
  "use strict";
  var DATA = $DATA;

  var width = 800, height = 600;
  var margin = { top: 40, right: 20, bottom: 40, left: 60 };
  var innerW = width - margin.left - margin.right;
  var innerH = height - margin.top - margin.bottom;

  function fmtCap(v) {
    if (v == null || isNaN(v)) return "-";
    var a = Math.abs(v);
    if (a >= 1e12) return "\$" + (v / 1e12).toFixed(2) + "T";
    if (a >= 1e9) return "\$" + (v / 1e9).toFixed(2) + "B";
    if (a >= 1e6) return "\$" + (v / 1e6).toFixed(2) + "M";
    if (a >= 1e3) return "\$" + (v / 1e3).toFixed(2) + "K";
    return "\$" + v.toFixed(2);
  }
  function fmtTick(v) {
    if (v === 0) return "0";
    if (v >= 1e12) return "\$" + d3.format(".2~f")(v / 1e12) + "T";
    return "\$" + d3.format(".0f")(v / 1e9) + "B";
  }
  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }

  var rows = DATA.filter(function (d) { return d.marketCap != null && !isNaN(d.marketCap); })
    .slice()
    .sort(function (a, b) { return d3.descending(a.marketCap, b.marketCap) || d3.ascending(a.ticker, b.ticker); });

  var sectors = Array.from(new Set(rows.map(function (d) { return d.sector; }))).sort();
  var color = d3.scaleOrdinal().domain(sectors).range(d3.schemeCategory10);

  var x = d3.scaleLinear().domain([0, d3.max(rows, function (d) { return d.marketCap; })]).nice().range([0, innerW]);
  var y = d3.scaleBand().domain(rows.map(function (d) { return d.ticker; })).range([0, innerH]).padding(0.15);

  var svg = d3.select("#chart-container").append("svg")
    .attr("id", "chart")
    .attr("width", width).attr("height", height)
    .attr("viewBox", "0 0 " + width + " " + height);

  svg.append("text").attr("class", "chart-title")
    .attr("x", margin.left).attr("y", 24)
    .text("Market capitalization of 40 companies, by sector");

  var g = svg.append("g").attr("transform", "translate(" + margin.left + "," + margin.top + ")");

  g.append("g").attr("class", "axis x-axis")
    .attr("transform", "translate(0," + innerH + ")")
    .call(d3.axisBottom(x).ticks(6).tickFormat(fmtTick));
  g.append("g").attr("class", "axis y-axis")
    .call(d3.axisLeft(y).tickSizeOuter(0));

  svg.append("text").attr("class", "axis-label")
    .attr("x", margin.left + innerW / 2).attr("y", height - 6)
    .attr("text-anchor", "middle")
    .text("Market cap (USD)");

  var tooltip = d3.select("#tooltip");

  g.append("g").attr("class", "bars").selectAll("rect.bar")
    .data(rows, function (d) { return d.ticker; })
    .join("rect")
    .attr("class", "bar")
    .attr("data-key", function (d) { return d.ticker; })
    .attr("x", 0)
    .attr("y", function (d) { return +y(d.ticker).toFixed(2); })
    .attr("width", function (d) { return +x(d.marketCap).toFixed(2); })
    .attr("height", +y.bandwidth().toFixed(2))
    .attr("fill", function (d) { return color(d.sector); })
    .on("mouseover", function (event, d) {
      tooltip.classed("visible", true)
        .html("<strong>" + esc(d.fullName) + "</strong> (" + esc(d.ticker) + ")<br/>" +
              "Market cap: " + fmtCap(d.marketCap) + "<br/>Sector: " + esc(d.sector))
        .style("left", (event.pageX + 10) + "px")
        .style("top", (event.pageY - 10) + "px");
    })
    .on("mousemove", function (event) {
      tooltip.style("left", (event.pageX + 10) + "px").style("top", (event.pageY - 10) + "px");
    })
    .on("mouseout", function () { tooltip.classed("visible", false); });

  // Legend: bottom-right of the plot area (bars there are short).
  var legend = g.append("g").attr("class", "legend")
    .attr("transform", "translate(" + (innerW - 190) + "," + (innerH - 20 - sectors.length * 18) + ")")
    .style("pointer-events", "none");
  legend.append("text").attr("x", 0).attr("y", -6).style("font-weight", "bold").text("Sector");
  var li = legend.selectAll("g.legend-item").data(sectors).join("g")
    .attr("class", "legend-item")
    .attr("transform", function (d, i) { return "translate(0," + (i * 18) + ")"; });
  li.append("rect").attr("width", 12).attr("height", 12).attr("fill", function (d) { return color(d); });
  li.append("text").attr("x", 18).attr("y", 10).text(function (d) { return d; });
})();
EOF
